def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        safe_bid = DAILY_SALARY * 0.2
        if hp <= 2 or no_water_days >= 2:
            safe_bid = DAILY_SALARY * 0.6
        return float(min(budget, safe_bid))

    prev_bids = []
    prev_neediness = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
        need = 0.0
        if opp.get('hp', 0) <= 2:
            need += 1.5
        elif opp.get('hp', 0) <= 4:
            need += 0.8
        if opp.get('no_water_days', 0) >= 2:
            need += 1.5
        elif opp.get('no_water_days', 0) == 1:
            need += 0.7
        if opp.get('budget', 0) > budget:
            need += 0.4
        prev_neediness.append(need)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0
    max_need = max(prev_neediness) if prev_neediness else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    urgency = 0.0
    if hp <= 2:
        urgency += 2.0
    elif hp <= 4:
        urgency += 1.0
    if no_water_days >= 2:
        urgency += 2.0
    elif no_water_days == 1:
        urgency += 0.8

    base = DAILY_SALARY * (0.28 + 0.42 * scarcity)

    if supply >= 23:
        base *= 0.8
    elif supply <= 17:
        base *= 1.2

    if urgency >= 3.0:
        target = max(base, DAILY_SALARY * 0.92)
    elif urgency >= 1.5:
        target = max(base, DAILY_SALARY * 0.72)
    else:
        target = base

    if highest_prev > 0:
        if highest_prev >= 120:
            if urgency < 1.5:
                target = min(target, DAILY_SALARY * 0.42)
            else:
                target = max(target, DAILY_SALARY * 0.88)
        elif highest_prev >= 90:
            if urgency < 1.5 and supply >= 20:
                target = min(target, DAILY_SALARY * 0.4)
            else:
                target = max(target, min(highest_prev + 2.0, DAILY_SALARY * 0.95))
        else:
            target = max(target, min(highest_prev + 1.5, DAILY_SALARY * 0.82))
    else:
        target = max(target, avg_prev * 0.9)

    if max_need >= 2.0 and supply <= 18:
        target += 8.0
    elif max_need >= 1.0 and supply <= 19:
        target += 4.0

    days_left = 11 - day
    reserve_floor = max(0.0, days_left * DAILY_SALARY * 0.18)
    affordable = max(0.0, budget - reserve_floor)

    if urgency >= 3.0:
        affordable = budget
    elif hp <= 3 and no_water_days >= 1:
        affordable = max(affordable, budget * 0.75)

    bid = min(target, affordable if affordable > 0 else budget)

    if bid < 0:
        bid = 0.0
    if urgency >= 3.0 and bid < DAILY_SALARY * 0.75:
        bid = min(budget, DAILY_SALARY * 0.75)
    if supply >= 24 and urgency == 0.0:
        bid = min(bid, DAILY_SALARY * 0.3)

    return float(min(budget, max(0.0, bid)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    # Collect yesterday's bids from alive opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and 'bid' in prev and prev['bid'] is not None:
            yesterday_bids.append(prev['bid'])

    # Supply factor: lower supply => need higher bid
    supply = day_context['supply']
    supply_factor = max(1.0, (MAX_SUPPLY - supply) / (MAX_SUPPLY - MIN_SUPPLY + 1) + 1.0)

    # HP urgency
    hp = my_status['hp']
    no_water = my_status['no_water_days']

    # Base bid strategy
    if yesterday_bids:
        highest_prev = max(yesterday_bids)
        # If we are desperate (low HP or already dehydrated)
        if hp <= 2 or no_water >= 1:
            target_bid = max(DAILY_SALARY * 0.9, highest_prev + 2.0)
        else:
            # Conservative: outbid only if previous was high, otherwise maintain moderate
            if highest_prev >= DAILY_SALARY * 0.75:
                target_bid = max(DAILY_SALARY * 0.6, highest_prev + 1.0)
            else:
                target_bid = DAILY_SALARY * 0.5
    else:
        # No history: moderate initial bid
        target_bid = DAILY_SALARY * 0.55

    # Apply supply factor (aggressive if supply low)
    if supply < 18:
        target_bid = max(target_bid, DAILY_SALARY * 0.7)

    # Ensure we don't exceed budget
    final_bid = min(my_status['budget'], max(1.0, target_bid))

    # Round to two decimals for consistency (optional but safe)
    return round(final_bid, 2)
